using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using Demo6.Game;
public class V10GuiSpy:MonoBehaviour{public int Count;public List<string> Events=new List<string>();void OnGUI(){Count++;if(Event.current.type!=EventType.Repaint&&Event.current.type!=EventType.Layout)Events.Add(Event.current.type+" "+Event.current.mousePosition);}}
public static class V10GuiProbe {
 public static async Task<object> Run(){if(!Application.dataPath.Contains("topdown-v10-review-isolated"))throw new Exception("isolated only");var go=new GameObject("V10 temporary GUI event probe");var spy=go.AddComponent<V10GuiSpy>();var type=typeof(Editor).Assembly.GetType("UnityEditor.GameView");var view=EditorWindow.GetWindow(type);view.Focus();var method=typeof(EditorGUIUtility).GetMethod("QueueGameViewInputEvent",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic,null,new[]{typeof(Event)},null);try{await Task.Delay(500);var at=DungeonHud.UtilityRect(0).center*DungeonUi.Scale;method.Invoke(null,new object[]{new Event{type=EventType.MouseDown,mousePosition=at,button=0}});await Task.Delay(150);method.Invoke(null,new object[]{new Event{type=EventType.MouseUp,mousePosition=at,button=0}});await Task.Delay(400);return new{point=at.ToString(),screen=new Vector2(Screen.width,Screen.height).ToString(),window=view.position.ToString(),modal=DungeonUi.Modal,events=spy.Events,count=spy.Count};}finally{UnityEngine.Object.Destroy(go);}}
}
